import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaCalendar, FaClock, FaMapMarkerAlt, FaUser, FaPrint } from 'react-icons/fa';
import axios from 'axios';
import './Display.css';
import Logo from '../components/Logo';

interface Announcement {
  id: string;
  title: string;
  description: string;
  date: string;
  time: string;
  venue?: string;
  program_title?: string;
  poster_image?: string;
  actors?: Array<{
    id: string;
    name: string;
    role?: string;
    role_in_program?: string;
  }>;
}

const Display: React.FC = () => {
  const navigate = useNavigate();
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState('');
  const [currentTime, setCurrentTime] = useState('');

  useEffect(() => {
    fetchAnnouncements();
    updateCurrentDate();
    updateCurrentTime();
    const dateInterval = setInterval(updateCurrentDate, 60000);
    const timeInterval = setInterval(updateCurrentTime, 1000);
    const announcementsInterval = setInterval(fetchAnnouncements, 60000);
    return () => {
      clearInterval(dateInterval);
      clearInterval(timeInterval);
      clearInterval(announcementsInterval);
    };
  }, []);

  const updateCurrentDate = () => {
    const now = new Date();
    const persianDate = now.toLocaleDateString('fa-IR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long'
    });
    setCurrentDate(persianDate);
  };

  const updateCurrentTime = () => {
    const now = new Date();
    const timeStr = now.toLocaleTimeString('fa-IR', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
    setCurrentTime(timeStr);
  };

  const fetchAnnouncements = async () => {
    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await axios.get(`/api/announcements?date=${today}&status=published`);
      setAnnouncements(response.data);
    } catch (error) {
    toast.error('خطا در دریافت آفیش‌ها');
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('fa-IR');
  };

  const handlePrint = () => {
    window.print();
  };

  if (loading) {
    return (
      <div className="display-loading">
        <div className="loading-spinner"></div>
  <p>در حال بارگذاری آفیش‌ها...</p>
      </div>
    );
  }

  return (
    <div className="display-container">
      <div className="print-logo" aria-hidden="true">
        <Logo src="/logo.png.jpg" height={144} width={144} alt="لوگو" />
      </div>
      <header className="display-header">
        <div className="header-content">
          <h1 className="system-title">سامانه رسا</h1>
          <div className="header-meta">
            <div className="current-date">{currentDate}</div>
            <div className="live-time">{currentTime}</div>
          </div>
          <button onClick={handlePrint} className="print-btn">
            <FaPrint />
            چاپ
          </button>
        </div>
      </header>

      <main className="display-main">
        {announcements.length === 0 ? (
          <div className="no-announcements">
            <FaCalendar />
  <h2>آفیشی برای امروز ثبت نشده است</h2>
  <p>جهت ثبت آفیش جدید به پنل مدیریت مراجعه کنید</p>
          </div>
        ) : (
          <div className="announcements-grid">
            {announcements.map(announcement => (
              <div key={announcement.id} className="announcement-card">
                {announcement.poster_image && (
                  <div className="card-image">
                    <img src={announcement.poster_image.startsWith('http') ? announcement.poster_image : `/uploads/${announcement.poster_image}`} alt={announcement.title} />
                  </div>
                )}

                <div className="card-content">
                  <h3 className="announcement-title">{announcement.title}</h3>

                  {announcement.description && (
                    <p className="announcement-description">{announcement.description}</p>
                  )}

                  {announcement.program_title && (
                    <div className="program-info">
                      <h4>برنامه: {announcement.program_title}</h4>
                    </div>
                  )}

                  <div className="announcement-details">
                    <div className="detail-item">
                      <FaCalendar />
                      <span>{formatDate(announcement.date)}</span>
                    </div>

                    <div className="detail-item">
                      <FaClock />
                      <span>{announcement.time}</span>
                    </div>

                    {announcement.venue && (
                      <div className="detail-item">
                        <FaMapMarkerAlt />
                        <span>{announcement.venue}</span>
                      </div>
                    )}
                  </div>

                  {announcement.actors && announcement.actors.length > 0 && (
                    <div className="actors-section">
                      <h4><FaUser /> عوامل</h4>
                      <div className="actors-list">
                        {announcement.actors.map(actor => (
                          <div key={actor.id} className="actor-item">
                            <span className="actor-name">{actor.name}</span>
                            <span className="actor-role">{actor.role || actor.role_in_program || ''}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      <footer className="display-footer">
        <p>© 2024 سامانه رسا</p>
      </footer>
    </div>
  );
};

export default Display;
